package io.github.chronicle.core.offering.temporary;

import com.google.gson.*;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import com.google.gson.Strictness;
import io.github.chronicle.core.history.ImmutableHistoryArchive;

import java.io.*;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.channels.FileLock;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;

/** Strict create-marked, externally-checked and atomically replaced temporary-offering store. */
public final class TemporaryOfferingStore implements AutoCloseable {
    public static final long MAX_FILE_BYTES=8L*1024*1024;
    private static final byte[] INITIALIZED="chronicle temporary offerings initialized v1\n".getBytes(StandardCharsets.US_ASCII);
    private static final Gson GSON=new GsonBuilder().setPrettyPrinting().disableHtmlEscaping().serializeNulls().create();
    private final Path file,marker,lockFile;private final ImmutableHistoryArchive history;private final FileChannel lockChannel;private final FileLock lock;
    private byte[] observedBytes;private TemporaryOfferingLedger observed;private boolean closed;
    public TemporaryOfferingStore(Path file)throws IOException{
        this.file=Objects.requireNonNull(file).toAbsolutePath().normalize();marker=sibling(".initialized");lockFile=sibling(".lock");history=new ImmutableHistoryArchive(this.file.resolveSibling("temporary-offering-history"),"temporary-offering",256*1024);
        Path parent=parent();Files.createDirectories(parent);if(Files.isSymbolicLink(parent)||Files.isSymbolicLink(file)||Files.isSymbolicLink(lockFile))throw new IOException("temporary offering paths must not be symbolic links");
        lockChannel=FileChannel.open(lockFile,StandardOpenOption.CREATE,StandardOpenOption.WRITE,LinkOption.NOFOLLOW_LINKS);FileLock acquired=lockChannel.tryLock();if(acquired==null){lockChannel.close();throw new IOException("temporary offering store is already open: "+file);}lock=acquired;
    }
    public synchronized TemporaryOfferingLedger loadOrCreate()throws IOException{
        open();boolean has=Files.exists(file,LinkOption.NOFOLLOW_LINKS),marked=Files.exists(marker,LinkOption.NOFOLLOW_LINKS),backup=Files.exists(sibling(".bak"),LinkOption.NOFOLLOW_LINKS);
        if(!has){if(marked||backup)throw new IOException("temporary offering authority is missing but prior evidence exists: "+file);writeMarker();writeInitial(encode(TemporaryOfferingLedger.EMPTY).getBytes(StandardCharsets.UTF_8));}
        else if(!marked)throw new IOException("temporary offering authority has no initialization marker: "+file);
        verifyMarker();byte[] bytes=current();TemporaryOfferingLedger ledger=decodeChecked(bytes);for(var claim:ledger.claims()){var archived=archived(claim.transaction());if(archived.isPresent()&&(!archived.get().equals(claim)||!TemporaryOfferingLedger.terminal(claim)))throw new IOException("live temporary claim conflicts with immutable history: "+claim.transaction());}return observe(bytes,ledger);
    }
    public synchronized TemporaryOfferingLedger save(TemporaryOfferingLedger candidate,TemporaryOfferingLedger expected)throws IOException{
        open();Objects.requireNonNull(candidate);if(observed==null||!observed.equals(expected))throw new IllegalStateException("temporary offering store state changed");validateReplacement(expected,candidate);
        byte[] old=verifyCurrent(observedBytes),next=encode(candidate).getBytes(StandardCharsets.UTF_8);replace(old,next);return observe(next,candidate);
    }
    public synchronized TemporaryOfferingLedger archiveTerminals(TemporaryOfferingLedger expected,java.util.function.Predicate<TemporaryOfferingClaim> filter)throws IOException{
        open();if(observed==null||!observed.equals(expected))throw new IllegalStateException("temporary offering store state changed");List<TemporaryOfferingClaim> terminal=expected.claims().stream().filter(TemporaryOfferingLedger::terminal).filter(filter).toList();if(terminal.isEmpty())return expected;
        for(var claim:terminal)history.publish(claim.transaction().toString(),encodeClaim(claim));return save(expected.removeArchived(terminal.stream().map(TemporaryOfferingClaim::transaction).toList()),expected);
    }
    public synchronized Optional<TemporaryOfferingClaim> archived(UUID transaction)throws IOException{open();Optional<byte[]> payload=history.read(transaction.toString());if(payload.isEmpty())return Optional.empty();TemporaryOfferingClaim claim=decodeClaim(payload.get());if(!claim.transaction().equals(transaction)||!TemporaryOfferingLedger.terminal(claim))throw new IOException("archived temporary offering identity/state is invalid");return Optional.of(claim);}
    public synchronized void verifyUnchanged()throws IOException{open();if(observed==null)throw new IllegalStateException("temporary offering store is not loaded");verifyCurrent(observedBytes);}
    @Override public synchronized void close()throws IOException{if(closed)return;closed=true;try{lock.release();}finally{lockChannel.close();}}
    public static String encode(TemporaryOfferingLedger ledger){
        JsonObject root=new JsonObject();root.addProperty("schema",1);root.addProperty("revision",ledger.revision());JsonArray claims=new JsonArray();
        for(var claim:ledger.claims()){JsonObject value=new JsonObject();value.addProperty("transaction",claim.transaction().toString());value.addProperty("player",claim.player().toString());value.addProperty("source",claim.source());value.addProperty("offering",claim.offering());value.addProperty("station",claim.station());value.addProperty("claimedAtTicks",claim.claimedAtTicks());value.addProperty("expiresAtTicks",claim.expiresAtTicks());value.addProperty("state",claim.state().name());if(claim.reviewedBy()!=null)value.addProperty("reviewedBy",claim.reviewedBy());else value.add("reviewedBy",JsonNull.INSTANCE);
            JsonObject terms=new JsonObject();terms.addProperty("durationTicks",claim.terms().durationTicks());terms.addProperty("health",claim.terms().health());terms.addProperty("exhaustionPercent",claim.terms().exhaustionPercent());JsonObject evidence=new JsonObject();claim.terms().evidence().forEach(evidence::addProperty);terms.add("evidence",evidence);value.add("terms",terms);claims.add(value);}
        root.add("claims",claims);JsonArray closed=new JsonArray();ledger.closedSources().forEach(closed::add);root.add("closedSources",closed);return GSON.toJson(root)+"\n";
    }
    public static TemporaryOfferingLedger decode(String text){
        JsonObject root=object(parse(text),"temporary offering ledger");exact(root,Set.of("schema","revision","claims","closedSources"),"ledger");if(number(root.get("schema"),"schema")!=1)throw bad("unsupported temporary offering schema");long revision=number(root.get("revision"),"revision");
        JsonArray values=array(root.get("claims"),"claims");if(values.size()>TemporaryOfferingLedger.MAX_CLAIMS)throw bad("too many temporary offering claims");ArrayList<TemporaryOfferingClaim> claims=new ArrayList<>();
        for(JsonElement element:values){JsonObject value=object(element,"claim");exact(value,Set.of("transaction","player","source","offering","station","claimedAtTicks","expiresAtTicks","terms","state","reviewedBy"),"claim");JsonObject terms=object(value.get("terms"),"terms");exact(terms,Set.of("durationTicks","health","exhaustionPercent","evidence"),"terms");JsonObject evidence=object(terms.get("evidence"),"evidence");if(evidence.size()>TemporaryOfferingTerms.MAX_EVIDENCE)throw bad("too much temporary offering evidence");TreeMap<String,String> facts=new TreeMap<>();for(var entry:evidence.entrySet())facts.put(entry.getKey(),string(entry.getValue(),entry.getKey()));
            TemporaryOfferingClaim.State state;try{state=TemporaryOfferingClaim.State.valueOf(string(value.get("state"),"state"));}catch(RuntimeException error){throw bad("invalid temporary offering state");}
            claims.add(new TemporaryOfferingClaim(uuid(value.get("transaction"),"transaction"),uuid(value.get("player"),"player"),string(value.get("source"),"source"),string(value.get("offering"),"offering"),string(value.get("station"),"station"),number(value.get("claimedAtTicks"),"claimedAtTicks"),number(value.get("expiresAtTicks"),"expiresAtTicks"),new TemporaryOfferingTerms(number(terms.get("durationTicks"),"durationTicks"),signed(terms.get("health"),"health"),signed(terms.get("exhaustionPercent"),"exhaustionPercent"),facts),state,value.get("reviewedBy").isJsonNull()?null:string(value.get("reviewedBy"),"reviewedBy")));}
        JsonArray closedValues=array(root.get("closedSources"),"closedSources");TreeSet<String> closed=new TreeSet<>();for(JsonElement item:closedValues)if(!closed.add(string(item,"closed source")))throw bad("duplicate closed source");return new TemporaryOfferingLedger(revision,claims,closed);
    }
    private void validateReplacement(TemporaryOfferingLedger before,TemporaryOfferingLedger after)throws IOException{
        if(after.revision()!=Math.addExact(before.revision(),1))throw new IllegalStateException("temporary offering revision must advance exactly once");Map<UUID,TemporaryOfferingClaim> old=new HashMap<>(),next=new HashMap<>();before.claims().forEach(c->old.put(c.transaction(),c));after.claims().forEach(c->next.put(c.transaction(),c));
        for(var entry:old.entrySet()){TemporaryOfferingClaim replacement=next.get(entry.getKey());if(replacement==null){if(!TemporaryOfferingLedger.terminal(entry.getValue()))throw new IllegalStateException("nonterminal temporary claim cannot be removed");TemporaryOfferingClaim archived=archived(entry.getKey()).orElseThrow(()->new IllegalStateException("terminal temporary claim must be archived before removal"));if(!archived.equals(entry.getValue()))throw new IllegalStateException("archived temporary claim conflicts with live authority");continue;}TemporaryOfferingClaim prior=entry.getValue();if(!prior.digest().equals(replacement.digest()))throw new IllegalStateException("temporary claim immutable identity changed");if(prior.state()!=replacement.state())TemporaryOfferingLedger.requireTransition(prior.state(),replacement.state());else if(!prior.equals(replacement))throw new IllegalStateException("temporary claim mutable state changed without a transition");}
        int additions=0;for(var entry:next.entrySet())if(!old.containsKey(entry.getKey())){if(++additions>1||entry.getValue().state()!=TemporaryOfferingClaim.State.CLAIMED)throw new IllegalStateException("temporary authority may add one claimed operation at a time");if(archived(entry.getKey()).isPresent())throw new IllegalStateException("archived temporary transaction cannot return to the live ledger");}
        if(!after.closedSources().containsAll(before.closedSources()))throw new IllegalStateException("temporary source closure cannot be reversed");
    }
    private static byte[] encodeClaim(TemporaryOfferingClaim claim){return encode(new TemporaryOfferingLedger(0,List.of(claim),Set.of())).getBytes(StandardCharsets.UTF_8);}
    private static TemporaryOfferingClaim decodeClaim(byte[] bytes)throws IOException{try{TemporaryOfferingLedger ledger=decode(new String(bytes,StandardCharsets.UTF_8));if(ledger.revision()!=0||ledger.claims().size()!=1||!ledger.closedSources().isEmpty())throw new IllegalArgumentException("archived temporary claim payload is not singular");return ledger.claims().getFirst();}catch(RuntimeException error){throw new IOException("archived temporary offering claim is invalid",error);}}
    private TemporaryOfferingLedger decodeChecked(byte[] bytes)throws IOException{try{return decode(new String(bytes,StandardCharsets.UTF_8));}catch(RuntimeException error){throw new IOException("temporary offering authority is invalid and was not replaced: "+file+" ("+error.getMessage()+")",error);}}
    private byte[] current()throws IOException{if(Files.isSymbolicLink(file)||!Files.isRegularFile(file,LinkOption.NOFOLLOW_LINKS)||Files.size(file)>MAX_FILE_BYTES)throw new IOException("temporary offering authority is not a bounded regular file: "+file);byte[] bytes=Files.readAllBytes(file);if(bytes.length>MAX_FILE_BYTES)throw new IOException("temporary offering authority exceeds 8 MiB");return bytes;}
    private void writeMarker()throws IOException{try(FileChannel channel=FileChannel.open(marker,StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE,LinkOption.NOFOLLOW_LINKS)){writeForce(channel,INITIALIZED);}catch(FileAlreadyExistsException error){throw new IOException("temporary offering marker appeared concurrently",error);}}
    private void verifyMarker()throws IOException{if(Files.isSymbolicLink(marker)||!Files.isRegularFile(marker,LinkOption.NOFOLLOW_LINKS)||Files.size(marker)!=INITIALIZED.length||!MessageDigest.isEqual(Files.readAllBytes(marker),INITIALIZED))throw new IOException("temporary offering marker is invalid: "+marker);}
    private void writeInitial(byte[] bytes)throws IOException{Path temporary=Files.createTempFile(parent(),file.getFileName().toString(),".tmp");try{forceWrite(temporary,bytes);try{Files.move(temporary,file,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException error){throw new IOException("atomic temporary offering creation unsupported",error);}}finally{Files.deleteIfExists(temporary);}}
    private void replace(byte[] old,byte[] replacement)throws IOException{Path temporary=Files.createTempFile(parent(),file.getFileName().toString(),".tmp"),backupTemporary=null;try{forceWrite(temporary,replacement);backupTemporary=Files.createTempFile(parent(),file.getFileName().toString(),".bak.tmp");forceWrite(backupTemporary,old);verifyCurrent(old);move(backupTemporary,sibling(".bak"));backupTemporary=null;verifyCurrent(old);move(temporary,file);}catch(IOException error){throw new IOException("unable to save temporary offering authority; published authority was not changed",error);}finally{Files.deleteIfExists(temporary);if(backupTemporary!=null)Files.deleteIfExists(backupTemporary);}}
    private TemporaryOfferingLedger observe(byte[] bytes,TemporaryOfferingLedger ledger){observedBytes=bytes.clone();observed=ledger;return ledger;}
    private byte[] verifyCurrent(byte[] expected)throws IOException{byte[] actual=current();if(!MessageDigest.isEqual(expected,actual))throw new IOException("temporary offering authority changed outside Chronicle: "+file);return actual;}
    private Path sibling(String suffix){return file.resolveSibling(file.getFileName()+suffix);}private Path parent()throws IOException{Path parent=file.getParent();if(parent==null)throw new IOException("temporary offering store has no parent");return parent;}
    private void open(){if(closed)throw new IllegalStateException("temporary offering store is closed");}
    private static void forceWrite(Path path,byte[] bytes)throws IOException{try(FileChannel channel=FileChannel.open(path,StandardOpenOption.WRITE,StandardOpenOption.TRUNCATE_EXISTING)){writeForce(channel,bytes);}}
    private static void writeForce(FileChannel channel,byte[] bytes)throws IOException{ByteBuffer buffer=ByteBuffer.wrap(bytes);while(buffer.hasRemaining())channel.write(buffer);channel.force(true);}
    private static void move(Path from,Path to)throws IOException{try{Files.move(from,to,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException error){throw new IOException("atomic temporary offering replacement unsupported",error);}}
    private static JsonElement parse(String source){if(source==null)throw bad("temporary offering JSON is required");validate(source);try(JsonReader reader=new JsonReader(new StringReader(source))){reader.setStrictness(Strictness.STRICT);JsonElement value=JsonParser.parseReader(reader);if(reader.peek()!=JsonToken.END_DOCUMENT)throw bad("trailing temporary offering JSON");return value;}catch(IOException error){throw bad("unable to parse temporary offering JSON");}}
    private static void validate(String source){try(JsonReader reader=new JsonReader(new StringReader(source))){reader.setStrictness(Strictness.STRICT);validate(reader,0);if(reader.peek()!=JsonToken.END_DOCUMENT)throw bad("trailing temporary offering JSON");}catch(IOException error){throw bad("unable to validate temporary offering JSON");}}
    private static void validate(JsonReader reader,int depth)throws IOException{if(depth>12)throw bad("temporary offering JSON nesting exceeds 12");switch(reader.peek()){case BEGIN_OBJECT->{reader.beginObject();Set<String> names=new HashSet<>();while(reader.hasNext()){String name=reader.nextName();if(!names.add(name))throw bad("duplicate temporary offering member: "+name);validate(reader,depth+1);}reader.endObject();}case BEGIN_ARRAY->{reader.beginArray();while(reader.hasNext())validate(reader,depth+1);reader.endArray();}case STRING,NUMBER->reader.nextString();case BOOLEAN->reader.nextBoolean();case NULL->reader.nextNull();default->throw bad("unexpected temporary offering JSON token");}}
    private static JsonObject object(JsonElement value,String name){if(value==null||!value.isJsonObject())throw bad(name+" must be an object");return value.getAsJsonObject();}private static JsonArray array(JsonElement value,String name){if(value==null||!value.isJsonArray())throw bad(name+" must be an array");return value.getAsJsonArray();}private static void exact(JsonObject object,Set<String> fields,String name){if(!object.keySet().equals(fields))throw bad(name+" fields do not match schema");}
    private static String string(JsonElement value,String name){if(value==null||!value.isJsonPrimitive()||!value.getAsJsonPrimitive().isString())throw bad(name+" must be a string");return value.getAsString();}private static long number(JsonElement value,String name){if(value==null||!value.isJsonPrimitive()||!value.getAsJsonPrimitive().isNumber()||!value.getAsString().matches("0|[1-9][0-9]*"))throw bad(name+" must be a canonical non-negative integer");try{return Long.parseLong(value.getAsString());}catch(NumberFormatException error){throw bad(name+" is outside long range");}}private static int signed(JsonElement value,String name){if(value==null||!value.isJsonPrimitive()||!value.getAsJsonPrimitive().isNumber()||!value.getAsString().matches("-?(0|[1-9][0-9]*)"))throw bad(name+" must be a canonical integer");try{return Integer.parseInt(value.getAsString());}catch(NumberFormatException error){throw bad(name+" is outside integer range");}}
    private static UUID uuid(JsonElement value,String name){String text=string(value,name);try{UUID id=UUID.fromString(text);if(!id.toString().equals(text))throw new IllegalArgumentException();return id;}catch(IllegalArgumentException error){throw bad(name+" must be a canonical UUID");}}
    private static IllegalArgumentException bad(String message){return new IllegalArgumentException(message);}
}
